ALTER TABLE authorities ADD COLUMN department TEXT;
CREATE TABLE authority_users(authority_id TEXT NOT NULL REFERENCES authorities(id), object_id TEXT NOT NULL, PRIMARY KEY(authority_id,object_id));
CREATE INDEX authority_users_identity ON authority_users(object_id,authority_id);
ALTER TABLE concerns ADD COLUMN alumnus_name TEXT;
ALTER TABLE concerns ADD COLUMN enrolment_number TEXT;
ALTER TABLE concerns ADD COLUMN alumni_number TEXT;
ALTER TABLE concerns ADD COLUMN requested_document TEXT;
ALTER TABLE concerns ADD COLUMN initial_category TEXT;
ALTER TABLE concerns ADD COLUMN initial_authority_id TEXT REFERENCES authorities(id);
ALTER TABLE concerns ADD COLUMN classifier_version TEXT NOT NULL DEFAULT 'rules-v1';
ALTER TABLE concerns ADD COLUMN simulated INTEGER NOT NULL DEFAULT 1 CHECK(simulated IN (0,1));
ALTER TABLE concerns ADD COLUMN forwarded_at TEXT;
ALTER TABLE concerns ADD COLUMN addressed_at TEXT;
ALTER TABLE concerns ADD COLUMN closed_at TEXT;
ALTER TABLE concerns ADD COLUMN fulfilled_at TEXT;
ALTER TABLE concerns ADD COLUMN reopen_count INTEGER NOT NULL DEFAULT 0 CHECK(reopen_count>=0);
ALTER TABLE concerns ADD COLUMN unresolved_count INTEGER NOT NULL DEFAULT 0 CHECK(unresolved_count>=0);
ALTER TABLE concerns ADD COLUMN first_routed_category TEXT;
ALTER TABLE concerns ADD COLUMN first_routed_authority_id TEXT REFERENCES authorities(id);
ALTER TABLE concerns ADD COLUMN due_at TEXT;
ALTER TABLE concerns ADD COLUMN due_override_at TEXT;
ALTER TABLE concerns ADD COLUMN next_reminder_at TEXT;
ALTER TABLE concerns ADD COLUMN routing_cycle INTEGER NOT NULL DEFAULT 0 CHECK(routing_cycle>=0);
ALTER TABLE concerns ADD COLUMN reminders_queued INTEGER NOT NULL DEFAULT 0 CHECK(reminders_queued>=0);
ALTER TABLE concerns ADD COLUMN escalation_queued INTEGER NOT NULL DEFAULT 0 CHECK(escalation_queued IN (0,1));
ALTER TABLE concerns ADD COLUMN reminder_blocked TEXT;
ALTER TABLE concerns ADD COLUMN escalation_blocked_reason TEXT;
CREATE INDEX concerns_due ON concerns(status,next_reminder_at);
CREATE TABLE reminder_policy(id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), due_hours INTEGER NOT NULL CHECK(due_hours BETWEEN 1 AND 8760), interval_hours INTEGER NOT NULL CHECK(interval_hours BETWEEN 1 AND 8760), max_reminders INTEGER NOT NULL CHECK(max_reminders BETWEEN 0 AND 20), escalation_delay_hours INTEGER NOT NULL CHECK(escalation_delay_hours BETWEEN 0 AND 8760), escalation_email TEXT);
INSERT INTO reminder_policy VALUES(1,1,24,24,2,24,NULL);
CREATE TABLE pilot_labels(concern_id INTEGER PRIMARY KEY REFERENCES concerns(id), category TEXT NOT NULL CHECK(category IN ('TRANSCRIPT','PROVISIONAL_DEGREE','DEGREE_VERIFICATION','MEDIUM_OF_INSTRUCTION','DEGREE_COLLECTION','MIGRATION','UNKNOWN')), authority_id TEXT REFERENCES authorities(id), labelled_by TEXT NOT NULL, rationale TEXT NOT NULL, labelled_at TEXT NOT NULL);
-- Rebuild outbox in one migration transaction; preserve IDs and every previous delivery.
DROP INDEX jobs_active;
ALTER TABLE jobs RENAME TO jobs_v2;
CREATE TABLE jobs(id INTEGER PRIMARY KEY, concern_id INTEGER NOT NULL REFERENCES concerns(id), kind TEXT NOT NULL CHECK(kind IN ('FORWARD','FOLLOWUP','ACK','REMINDER','ESCALATION')), state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','RUNNING','SUCCEEDED','FAILED','UNCERTAIN','CANCELLED')), recipient TEXT NOT NULL, approved_by TEXT, approved_version INTEGER, draft_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, dry_run INTEGER NOT NULL CHECK(dry_run IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, delivery_key TEXT UNIQUE, routing_cycle INTEGER, outbound_checked_at TEXT, CHECK(kind!='FORWARD' OR (approved_by IS NOT NULL AND approved_version IS NOT NULL)));
INSERT INTO jobs(id,concern_id,kind,state,recipient,approved_by,approved_version,draft_id,attempts,error,dry_run,created_at,updated_at) SELECT id,concern_id,kind,state,recipient,approved_by,approved_version,draft_id,attempts,error,dry_run,created_at,updated_at FROM jobs_v2;
DROP TABLE jobs_v2;
CREATE UNIQUE INDEX jobs_active ON jobs(concern_id,kind) WHERE state IN ('PENDING','RUNNING','UNCERTAIN');
CREATE INDEX jobs_state ON jobs(state,id);
CREATE TABLE outbound_messages(message_id TEXT PRIMARY KEY, concern_id INTEGER NOT NULL REFERENCES concerns(id), job_id INTEGER NOT NULL REFERENCES jobs(id));
UPDATE concerns SET initial_category=coalesce((SELECT json_extract(a.details,'$.category') FROM audit a WHERE a.concern_id=concerns.id AND a.event='CLASSIFIED' ORDER BY a.id LIMIT 1),'UNKNOWN');
UPDATE concerns SET requested_document=CASE WHEN category!='UNKNOWN' THEN category END;
UPDATE concerns SET initial_authority_id=(SELECT authority_id FROM routes WHERE routes.category=concerns.initial_category);
UPDATE concerns SET simulated=0 WHERE EXISTS(SELECT 1 FROM jobs j WHERE j.concern_id=concerns.id AND j.dry_run=0);
-- Legacy timing cannot be inferred from updated_at. Recover only explicit audited transitions.
UPDATE concerns SET forwarded_at=(SELECT created_at FROM audit WHERE concern_id=concerns.id AND event='STATUS_CHANGED' AND json_extract(details,'$.to')='FORWARDED' ORDER BY id DESC LIMIT 1), addressed_at=(SELECT created_at FROM audit WHERE concern_id=concerns.id AND event='STATUS_CHANGED' AND json_extract(details,'$.to')='ADDRESSED' ORDER BY id DESC LIMIT 1), closed_at=CASE WHEN status='CLOSED' THEN (SELECT created_at FROM audit WHERE concern_id=concerns.id AND event='STATUS_CHANGED' AND json_extract(details,'$.to')='CLOSED' ORDER BY id DESC LIMIT 1) END;
UPDATE concerns SET due_at=strftime('%Y-%m-%dT%H:%M:%f+00:00',forwarded_at,'+24 hours'),next_reminder_at=strftime('%Y-%m-%dT%H:%M:%f+00:00',forwarded_at,'+24 hours'),routing_cycle=1 WHERE status='FORWARDED' AND forwarded_at IS NOT NULL;
INSERT INTO schema_migrations VALUES(3);
